package vip.xiaonuo.srm.collaboration;
import java.util.*;
import java.math.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import vip.xiaonuo.common.exception.CommonException;
import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;
import static vip.xiaonuo.srm.collaboration.CollaborationStore.*;
import static vip.xiaonuo.srm.collaboration.CollaborationRules.*;
import static vip.xiaonuo.srm.collaboration.CollaborationInputs.*;

@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class SettlementService {
 final CollaborationStore x;
 void participant(Context a){if(a.portal())x.finance(a);else x.buyer(a);}
 public Map<String,Object> create(Context a,Reconciliation p){x.buyer(a);x.access.requireSupplier(a,p.supplierId(),true);String hash=x.hash(p);var old=x.db.queryForList("SELECT ID,REQUEST_HASH FROM SRM_COL_RECON WHERE ORG_ID=? AND REQUEST_KEY=?",a.orgId(),p.requestKey());if(!old.isEmpty()){require(hash.equals(old.get(0).get("REQUEST_HASH")),409,"对账请求键内容冲突");return detail(a,s(old.get(0),"ID"));}var ids=new TreeSet<>(p.receiptLineIds());require(ids.size()==p.receiptLineIds().size(),400,"实收行重复");String slots=String.join(",",Collections.nCopies(ids.size(),"?"));var args=new ArrayList<Object>(ids);args.add(p.supplierId());args.add(a.orgId());var first=x.db.queryForList("SELECT DISTINCT r.PO_ID FROM SRM_COL_RECEIPT_LINE l JOIN SRM_COL_RECEIPT r ON r.ID=l.RECEIPT_ID WHERE l.ID IN ("+slots+") AND r.SUPPLIER_ID=? AND r.ORG_ID=? ORDER BY r.PO_ID",args.toArray());for(var po:first)x.po(a,s(po,"PO_ID"),true);var lines=x.db.queryForList("SELECT l.*,r.STATUS AS RECEIPT_STATUS,p.CURRENCY,p.MODE FROM SRM_COL_RECEIPT_LINE l JOIN SRM_COL_RECEIPT r ON r.ID=l.RECEIPT_ID JOIN SRM_COL_PO p ON p.ID=r.PO_ID WHERE l.ID IN ("+slots+") AND r.SUPPLIER_ID=? AND r.ORG_ID=? ORDER BY l.ID FOR UPDATE",args.toArray());require(lines.size()==ids.size(),404,"部分实收行不存在或无权访问");String currency=s(lines.get(0),"CURRENCY"),mode=s(lines.get(0),"MODE");BigDecimal qty=BigDecimal.ZERO,total=BigDecimal.ZERO;for(var line:lines){require("POSTED".equals(line.get("RECEIPT_STATUS"))&&line.get("ALLOC_RECON_ID")==null,409,"实收已经作废或被其他对账单占用");require(currency.equals(line.get("CURRENCY"))&&mode.equals(line.get("MODE")),400,"不同币种或沙箱/真实来源不能混合对账");qty=qty.add(x.decimal(line.get("QUANTITY")));total=total.add(x.clearAmount(line,"AMOUNT_CIPHER"));}money(total);require(total.signum()>0,400,"对账金额必须大于零");String id=id();try{x.db.update("INSERT INTO SRM_COL_RECON(ID,ORG_ID,SUPPLIER_ID,REC_NO,CURRENCY,MODE,STATUS,QUANTITY,AMOUNT_CIPHER,BASIS_HASH,CREATED_BY,CREATED_AT,REQUEST_KEY,REQUEST_HASH) VALUES(?,?,?,?,?,?,'WAITING_CONFIRMATION',?,?,?,?,NOW(3),?,?)",id,a.orgId(),p.supplierId(),p.recNo()==null||p.recNo().isBlank()?"REC"+id:p.recNo(),currency,mode,qty,x.crypto.encrypt(total.toPlainString()),basis(lines),a.userId(),p.requestKey(),hash);}catch(org.springframework.dao.DuplicateKeyException e){throw new CommonException(409,"对账单编号已存在");}for(var line:lines){var r=x.db.queryForMap("SELECT PO_ID FROM SRM_COL_RECEIPT WHERE ID=?",line.get("RECEIPT_ID"));x.db.update("INSERT INTO SRM_COL_RECON_LINE(ID,RECON_ID,RECEIPT_LINE_ID,PO_ID,PO_LINE_ID,QUANTITY,UNIT_PRICE_CIPHER,AMOUNT_CIPHER) VALUES(?,?,?,?,?,?,?,?)",id(),id,line.get("ID"),r.get("PO_ID"),line.get("PO_LINE_ID"),line.get("QUANTITY"),line.get("UNIT_PRICE_CIPHER"),line.get("AMOUNT_CIPHER"));require(x.db.update("UPDATE SRM_COL_RECEIPT_LINE SET ALLOC_RECON_ID=? WHERE ID=? AND ALLOC_RECON_ID IS NULL",id,line.get("ID"))==1,409,"实收已被并发占用");}var rec=x.recon(a,id,false);action(a,id,"CREATED",Map.of("receiptLines",ids.size()));x.notifyBoth(rec,id,"RECON_CREATED","新对账单待双方核对确认",id+":created");x.audit(a,p.supplierId(),id,"RECON_CREATED",Map.of("receiptLineCount",ids.size()));return detail(a,id);}
 String basis(List<Map<String,Object>> lines){var data=new ArrayList<Map<String,Object>>();for(var row:lines)data.add(Map.of("id",row.get("ID"),"quantity",row.get("QUANTITY"),"unitPriceCipher",row.get("UNIT_PRICE_CIPHER"),"amountCipher",row.get("AMOUNT_CIPHER"),"poVersion",row.get("PO_VERSION")));return x.hash(data);}
 void validate(Map<String,Object> rec){var lines=x.db.queryForList("SELECT l.*,r.STATUS AS RECEIPT_STATUS FROM SRM_COL_RECEIPT_LINE l JOIN SRM_COL_RECEIPT r ON r.ID=l.RECEIPT_ID JOIN SRM_COL_RECON_LINE q ON q.RECEIPT_LINE_ID=l.ID WHERE q.RECON_ID=? ORDER BY l.ID",rec.get("ID"));require(!lines.isEmpty()&&lines.stream().allMatch(l->"POSTED".equals(l.get("RECEIPT_STATUS"))&&rec.get("ID").equals(l.get("ALLOC_RECON_ID")))&&basis(lines).equals(rec.get("BASIS_HASH")),409,"实收依据已变化，不能确认或推送旧账单");}
 public Map<String,Object> page(Context a,int current,int size){participant(a);require(current>=1&&size>=1&&size<=100,400,"分页范围无效");var args=new ArrayList<Object>();String where=x.where(a,args,"r");long total=x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_RECON r WHERE "+where,Long.class,args.toArray());args.add(size);args.add((current-1)*size);var rows=x.db.queryForList("SELECT r.*,s.NAME AS SUPPLIER_NAME FROM SRM_COL_RECON r JOIN SRM_SUPPLIER s ON s.ID=r.SUPPLIER_ID WHERE "+where+" ORDER BY r.CREATED_AT DESC,r.ID DESC LIMIT ? OFFSET ?",args.toArray());var out=new ArrayList<Map<String,Object>>();for(var row:rows){var item=x.basic(row,new String[][]{{"id","ID"},{"recNo","REC_NO"},{"supplierName","SUPPLIER_NAME"},{"currency","CURRENCY"},{"mode","MODE"},{"status","STATUS"},{"rowVersion","ROW_VERSION"},{"quantity","QUANTITY"},{"buyerConfirmed","BUYER_CONFIRMED"},{"supplierConfirmed","SUPPLIER_CONFIRMED"}});item.put("amount",x.clearAmount(row,"AMOUNT_CIPHER"));out.add(item);}return Map.of("total",total,"records",out);}
 public Map<String,Object> detail(Context a,String id){participant(a);var r=x.recon(a,id,false);var out=x.basic(r,new String[][]{{"id","ID"},{"supplierId","SUPPLIER_ID"},{"recNo","REC_NO"},{"currency","CURRENCY"},{"mode","MODE"},{"status","STATUS"},{"rowVersion","ROW_VERSION"},{"quantity","QUANTITY"},{"buyerConfirmed","BUYER_CONFIRMED"},{"supplierConfirmed","SUPPLIER_CONFIRMED"},{"invoiceId","INVOICE_ID"}});out.put("amount",x.clearAmount(r,"AMOUNT_CIPHER"));var lines=new ArrayList<Map<String,Object>>();for(var row:x.db.queryForList("SELECT q.*,p.PO_NO,l.MATERIAL,r.RECEIPT_NO FROM SRM_COL_RECON_LINE q JOIN SRM_COL_PO p ON p.ID=q.PO_ID JOIN SRM_COL_PO_LINE l ON l.ID=q.PO_LINE_ID JOIN SRM_COL_RECEIPT_LINE rl ON rl.ID=q.RECEIPT_LINE_ID JOIN SRM_COL_RECEIPT r ON r.ID=rl.RECEIPT_ID WHERE q.RECON_ID=? ORDER BY q.ID",id)){var item=x.basic(row,new String[][]{{"id","ID"},{"poNo","PO_NO"},{"material","MATERIAL"},{"receiptNo","RECEIPT_NO"},{"quantity","QUANTITY"}});item.put("amount",x.clearAmount(row,"AMOUNT_CIPHER"));if(x.price(a))item.put("unitPrice",x.clearAmount(row,"UNIT_PRICE_CIPHER"));lines.add(item);}out.put("lines",lines);var actions=new ArrayList<Map<String,Object>>();for(var row:x.db.queryForList("SELECT * FROM SRM_COL_RECON_ACTION WHERE RECON_ID=? ORDER BY CREATED_AT,ID",id)){var item=x.basic(row,new String[][]{{"action","ACTION"},{"portal","PORTAL"},{"createdAt","CREATED_AT"}});item.put("content",x.object(x.crypto.decrypt(s(row,"CONTENT_CIPHER"))));actions.add(item);}out.put("history",actions);out.put("cases",x.db.queryForList("SELECT ID AS id,KIND AS kind,STATUS AS status,CREATED_AT AS createdAt FROM SRM_COL_CASE WHERE BUSINESS_ID=? AND KIND='RECON_DISPUTE' ORDER BY CREATED_AT DESC",id));return out;}
 void action(Context a,String id,String action,Object content){x.db.update("INSERT INTO SRM_COL_RECON_ACTION(ID,RECON_ID,ACTION,ACTOR_ID,PORTAL,CONTENT_CIPHER,CREATED_AT) VALUES(?,?,?,?,?,?,NOW(3))",id(),id,action,a.userId(),a.portal(),x.crypto.encrypt(x.json(content)));}
 void financeLock(Map<String,Object> rec){if(rec.get("INVOICE_ID")!=null){var inv=x.db.queryForMap("SELECT STATUS FROM SRM_COL_INVOICE WHERE ID=?",rec.get("INVOICE_ID"));require(!Set.of("AWAITING_RECEIPT","ACCEPTED","PARTIALLY_PAID","PAID").contains(s(inv,"STATUS")),409,"已进入财务受理，不能回退账单；请核查回执并协同财务处理");}}
 public Map<String,Object> confirm(Context a,String id,Confirmation p){participant(a);var r=x.lockRecon(a,id);validate(r);String flag=a.portal()?"SUPPLIER_CONFIRMED":"BUYER_CONFIRMED";if(Boolean.TRUE.equals(r.get(flag))&&Set.of("WAITING_CONFIRMATION","CONFIRMED").contains(s(r,"STATUS")))return detail(a,id);x.version(r,p.rowVersion());require(s(r,"STATUS").equals("WAITING_CONFIRMATION"),409,"须先解决差异或争议后重新双确认");boolean buyer=a.portal()?Boolean.TRUE.equals(r.get("BUYER_CONFIRMED")):true,supplier=a.portal()?true:Boolean.TRUE.equals(r.get("SUPPLIER_CONFIRMED"));x.db.update("UPDATE SRM_COL_RECON SET BUYER_CONFIRMED=?,SUPPLIER_CONFIRMED=?,STATUS=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",buyer,supplier,buyer&&supplier?"CONFIRMED":"WAITING_CONFIRMATION",id);action(a,id,a.portal()?"SUPPLIER_CONFIRMED":"BUYER_CONFIRMED",Map.of("comment",p.comment(),"basisHash",r.get("BASIS_HASH")));x.notifyBoth(r,id,"RECON_CONFIRMATION",buyer&&supplier?"对账双方已确认":"对账已有一方确认，等待另一方",id+":confirm:"+(n(r,"ROW_VERSION")+1));x.audit(a,s(r,"SUPPLIER_ID"),id,"RECON_CONFIRMED_BY_PARTY",Map.of("portal",a.portal(),"basisHash",r.get("BASIS_HASH")));return detail(a,id);}
 public Map<String,Object> difference(Context a,String id,Opinion p){participant(a);var r=x.lockRecon(a,id);x.version(r,p.rowVersion());financeLock(r);require(!s(r,"STATUS").equals("WITHDRAWN"),409,"对账单已撤回");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_CASE WHERE BUSINESS_ID=? AND KIND='RECON_DISPUTE' AND STATUS='PENDING'",Long.class,id)==0,409,"争议已升级审批，请先处理该任务");x.db.update("UPDATE SRM_COL_RECON SET STATUS='DIFFERENCE',BUYER_CONFIRMED=false,SUPPLIER_CONFIRMED=false,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",id);action(a,id,"DIFFERENCE_REPORTED",p);x.notifyBoth(r,id,"RECON_DIFFERENCE","对账存在差异，请核对并协商",id+":diff:"+(n(r,"ROW_VERSION")+1));x.audit(a,s(r,"SUPPLIER_ID"),id,"RECON_DIFFERENCE_REPORTED",Map.of("portal",a.portal()));return detail(a,id);}
 public Map<String,Object> discuss(Context a,String id,Opinion p){participant(a);var r=x.lockRecon(a,id);x.version(r,p.rowVersion());require(!s(r,"STATUS").equals("WITHDRAWN"),409,"对账单已撤回");action(a,id,"DISCUSSION",Map.of("comment",p.comment()));x.db.update("UPDATE SRM_COL_RECON SET ROW_VERSION=ROW_VERSION+1 WHERE ID=?",id);return detail(a,id);}
 public Map<String,Object> resolve(Context a,String id,Opinion p){x.buyer(a);var r=x.lockRecon(a,id);x.version(r,p.rowVersion());financeLock(r);validate(r);require(Set.of("DIFFERENCE","DISPUTED").contains(s(r,"STATUS")),409,"当前无待解决差异");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_CASE WHERE BUSINESS_ID=? AND KIND='RECON_DISPUTE' AND STATUS='PENDING'",Long.class,id)==0,409,"经理升级任务仍在处理");x.db.update("UPDATE SRM_COL_RECON SET STATUS='WAITING_CONFIRMATION',BUYER_CONFIRMED=false,SUPPLIER_CONFIRMED=false,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",id);action(a,id,"RESOLUTION_PROPOSED",Map.of("comment",p.comment(),"basisHash",r.get("BASIS_HASH")));x.notifyBoth(r,id,"RECON_RESOLVED","已提交差异解决意见，请双方重新确认当前账单",id+":resolve:"+(n(r,"ROW_VERSION")+1));return detail(a,id);}
 public void withdraw(Context a,String id,Opinion p){x.buyer(a);var r=x.lockRecon(a,id);x.version(r,p.rowVersion());require(a.userId().equals(r.get("CREATED_BY"))||a.roles().contains("superAdmin"),403,"仅创建人或管理员可撤回");require(r.get("INVOICE_ID")==null&&!Boolean.TRUE.equals(r.get("BUYER_CONFIRMED"))&&!Boolean.TRUE.equals(r.get("SUPPLIER_CONFIRMED"))&&!s(r,"STATUS").equals("WITHDRAWN"),409,"已确认或有发票的账单不能直接撤回");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_CASE WHERE BUSINESS_ID=? AND STATUS='PENDING'",Long.class,id)==0,409,"仍有经理处理任务");x.db.update("UPDATE SRM_COL_RECON SET STATUS='WITHDRAWN',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",id);x.db.update("UPDATE SRM_COL_RECEIPT_LINE SET ALLOC_RECON_ID=NULL WHERE ALLOC_RECON_ID=?",id);action(a,id,"WITHDRAWN",Map.of("comment",p.comment()));x.audit(a,s(r,"SUPPLIER_ID"),id,"RECON_WITHDRAWN",Map.of("reason",p.comment()));}
}
